const data = {
 llm1:{title:'模型调用 01',kind:'LLM GENERATION',start:0,end:4.2,turn:'Turn 01',parent:'用户问题',output:'先读取认证逻辑，同时运行相关测试。\n工具调用：read、bash。',phases:[['等待首个事件',0,.6],['可见 thinking',.6,2.6],['生成工具参数',2.6,4.2]]},
 read:{title:'read',kind:'TOOL EXECUTION',start:4.2,end:6,turn:'Turn 01',parent:'模型调用 01',output:'session.ts:42\nif (session.expiresAt < now) {\n  return { authenticated: false };\n}',phases:[]},
 bash:{title:'bash',kind:'TOOL EXECUTION',start:4.2,end:10.4,turn:'Turn 01',parent:'模型调用 01',output:'FAIL auth/session.test.ts\n✗ rejects a session at its expiry boundary\nExpected: false\nReceived: true\nExit code: 1',phases:[],error:true},
 llm2:{title:'模型调用 02',kind:'LLM GENERATION',start:10.4,end:15.2,turn:'Turn 02',parent:'read + bash',output:'失败来自过期时间的边界判断。当前代码只检查 expiresAt < now，因此恰好等于当前时间时，session 仍被接受。将判断改为 <=，并保留该边界测试。',phases:[['等待首个事件',10.4,10.8],['可见 thinking',10.8,11.6],['文本输出',11.6,15.2]]},
 answer:{title:'回答完成',kind:'QUESTION RESULT',start:15.2,end:15.2,turn:'问题 01',parent:'模型调用 02',output:'已解释过期边界的根因，并给出修复建议。',phases:[]}
};
let time=12.4,selected='llm2',tab='input',timer=null,mode='live',collapsed=false;
const graph=document.querySelector('#graph');
const fmt=n=>n.toFixed(1)+' s';
function state(d){return time<d.start?'尚未开始':time<d.end?'运行中':d.error?'失败':'已完成'}
function duration(d){return Math.max(0,Math.min(time,d.end)-d.start)}
function setText(id,value){document.getElementById(id).textContent=value}
function card(label,body){const box=document.createElement('div');box.className='input-card';const l=document.createElement('div');l.className='label';l.textContent=label;const p=document.createElement('p');p.textContent=body;box.append(l,p);return box}
function renderDetails(){const d=data[selected];setText('detail-title',d.title);setText('detail-type',d.kind);setText('detail-state',state(d));setText('detail-start',time>=d.start?fmt(d.start):'尚未发生');setText('detail-duration',fmt(duration(d)));setText('detail-turn',d.turn);setText('detail-parent',d.parent);document.querySelector('#phase-section').hidden=!d.phases.length;
const phases=document.querySelector('#phases');phases.replaceChildren();d.phases.forEach(([label,start,end])=>{const p=document.createElement('div');p.className='phase'+(time>=start&&time<end?' active':'');const a=document.createElement('span');a.textContent=label;const b=document.createElement('b');b.textContent=time<start?'未开始':time<end?'进行中':fmt(end-start);p.append(a,b);phases.append(p)});
const content=document.querySelector('#detail-content');content.replaceChildren();if(time<d.start){content.append(card('此时刻尚无记录','向后移动时间游标，查看此调用开始后的信息。'));return}
if(tab==='input'){if(selected==='llm2'){content.append(card('USER · 当前问题','找出测试失败的原因'),card('TOOL RESULT · read','session.ts · 已读取认证判断'),card('TOOL RESULT · bash','1 个测试失败 · Exit code 1'))}else if(selected==='read'){content.append(card('ARGUMENTS','{ "path": "src/auth/session.ts" }'))}else if(selected==='bash'){content.append(card('ARGUMENTS','{ "command": "pnpm test auth" }'))}else{content.append(card('USER · 当前问题','读取认证逻辑，运行测试，并解释失败原因。'))}}
else if(tab==='output'){if(time<d.end){content.append(card('输出仍在生成','阶段回放展示状态变化；完整结果在调用结束后可见。'))}else{content.append(card('已完成输出',d.output))}}
else{const pre=document.createElement('pre');const type=d.kind==='TOOL EXECUTION'?'tool_execution_start':'before_provider_request';pre.textContent=JSON.stringify({type,traceId:'question-01',spanId:selected,relativeTime:d.start,...(time>=d.end?{end:d.end,state:d.error?'error':'ok'}:{state:'running'})},null,2);content.append(pre)}
}
function drawEdges(){const box=graph.getBoundingClientRect();const svg=document.querySelector('#edges');svg.setAttribute('viewBox',`0 0 ${box.width} ${box.height}`);svg.replaceChildren();const pairs=collapsed?[['summary','llm2'],['llm2','answer']]:[['llm1','read'],['llm1','bash'],['read','llm2'],['bash','llm2'],['llm2','answer']];const mobile=window.innerWidth<=760;pairs.forEach(([a,b])=>{const from=document.getElementById(a),to=document.getElementById(b);if(from.hidden||to.hidden||getComputedStyle(from).display==='none'||getComputedStyle(to).display==='none')return;const r=from.getBoundingClientRect(),s=to.getBoundingClientRect();let x1,y1,x2,y2,path;if(mobile){x1=r.left+r.width/2-box.left;y1=r.bottom-box.top;x2=s.left+s.width/2-box.left;y2=s.top-box.top;const mid=(y1+y2)/2;path=`M ${x1} ${y1} C ${x1} ${mid},${x2} ${mid},${x2} ${y2}`}else{x1=r.right-box.left;y1=r.top+r.height/2-box.top;x2=s.left-box.left;y2=s.top+s.height/2-box.top;const mid=(x1+x2)/2;path=`M ${x1} ${y1} C ${mid} ${y1},${mid} ${y2},${x2} ${y2}`}
const el=document.createElementNS('http://www.w3.org/2000/svg','path');el.setAttribute('d',path);el.setAttribute('fill','none');el.setAttribute('stroke',b===selected?'#a396d9':'#c9cedc');el.setAttribute('stroke-width','1.5');svg.append(el);const dot=document.createElementNS('http://www.w3.org/2000/svg','circle');dot.setAttribute('cx',String(x2));dot.setAttribute('cy',String(y2));dot.setAttribute('r','2.5');dot.setAttribute('fill',b===selected?'#a396d9':'#c9cedc');svg.append(dot)})}
function render(){if(time<10.4&&collapsed){collapsed=false;graph.classList.remove('collapsed');setText('collapse','折叠第一轮')}Object.entries(data).forEach(([id,d])=>{const el=document.getElementById(id);el.hidden=time<d.start;el.classList.toggle('selected',id===selected);el.classList.toggle('is-running',state(d)==='运行中');el.classList.toggle('is-failed',state(d)==='失败');el.querySelector('.node-status').textContent=state(d)==='已完成'?'✓ 完成':state(d)==='失败'?'! 失败':'● 运行';el.querySelector('.node-time').textContent=fmt(duration(d));if(id==='llm2')el.querySelector('.phase-label').textContent=time>=d.end?'文本生成完成':time<10.8?'等待响应':time<11.6?'可见 thinking':'文本输出中'});graph.classList.toggle('has-answer',time>=15.2);document.querySelector('#parallel-label').hidden=time<4.2;document.querySelector('.round-two').hidden=time<10.4;document.querySelector('#summary').hidden=!collapsed;document.querySelector('#collapse').disabled=time<10.4;
const running=Object.values(data).filter(d=>state(d)==='运行中');setText('activity',running.length>1?'● 2 个工具并行执行':running[0]?.title.startsWith('模型')?'● '+(running[0].phases.find(([,a,b])=>time>=a&&time<b)?.[0]||'模型运行中'):running[0]?'● '+running[0].title+' 运行中':'✓ 本次问题完成');document.querySelector('#elapsed').innerHTML=time.toFixed(1)+'<span> s</span>';setText('mode-label',mode==='live'?'模拟实时状态':'阶段回放');setText('cursor-label',fmt(time)+' / 15.2 s');document.querySelector('#scrub').value=time;setText('graph-caption',time<4.2?'模型读取问题，生成工具调用参数。':time<6?'两个工具同时运行，分别记录起止时间。':time<10.4?'read 已完成，bash 仍在执行。':time<15.2?'工具失败被带入下一轮，agent 继续分析。':'问题完成。工具失败不等于整个 agent 任务失败。');
document.querySelectorAll('.lane').forEach(el=>{const d=data[el.dataset.id];el.classList.toggle('selected',el.dataset.id===selected);const bar=el.querySelector('.bar');bar.hidden=time<d.start;bar.style.left=d.start/16*100+'%';bar.style.width=duration(d)/16*100+'%';bar.textContent=fmt(duration(d));el.querySelector('.cursor').style.left=time/16*100+'%';el.setAttribute('aria-label',`${d.title}，${state(d)}，${fmt(duration(d))}`)});renderDetails();requestAnimationFrame(drawEdges)}
Object.entries(data).filter(([id])=>id!=='answer').forEach(([id,d])=>{const lane=document.createElement('button');lane.className='lane';lane.dataset.id=id;lane.innerHTML=`<span class="lane-label"><i></i>${d.title}</span><span class="track"><span class="bar"></span><span class="cursor"></span></span>`;document.querySelector('#lanes').append(lane)});
document.querySelectorAll('[data-id]').forEach(el=>el.addEventListener('click',()=>{selected=el.dataset.id;render();if(window.innerWidth<=760)document.querySelector('#inspector').classList.add('open')}));document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>{tab=el.dataset.tab;document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('selected',t===el);t.setAttribute('aria-selected',String(t===el))});renderDetails()}));
function stop(){clearInterval(timer);timer=null;setText('play','▶ 播放');document.querySelector('#play').setAttribute('aria-label','播放阶段回放')}
document.querySelector('#scrub').addEventListener('input',e=>{stop();mode='replay';time=Number(e.target.value);if(time<10.4&&collapsed){collapsed=false;graph.classList.remove('collapsed');setText('collapse','折叠第一轮')}render()});
document.querySelector('#play').addEventListener('click',()=>{if(timer){stop();return}mode='replay';if(time>=15.2)time=0;setText('play','Ⅱ 暂停');document.querySelector('#play').setAttribute('aria-label','暂停阶段回放');timer=setInterval(()=>{time=Math.min(15.2,time+.1*Number(document.querySelector('#speed').value));render();if(time>=15.2)stop()},100)});
document.querySelector('#live').addEventListener('click',()=>{stop();mode='live';time=12.4;render()});document.querySelector('#collapse').addEventListener('click',()=>{collapsed=!collapsed;graph.classList.toggle('collapsed',collapsed);setText('collapse',collapsed?'展开第一轮':'折叠第一轮');render()});document.querySelector('#close-detail').addEventListener('click',()=>document.querySelector('#inspector').classList.remove('open'));window.addEventListener('resize',drawEdges);render();
